const DATABASE_ENGINE_BRANDS: Readonly<Record<string, BrandMarkKey>> = {
  clickhouse: "clickhouse",
  elasticsearch: "elasticsearch",
  mariadb: "mariadb",
  mongo: "mongodb",
  mongodb: "mongodb",
  mysql: "mysql",
  pg: "postgresql",
  postgres: "postgresql",
  postgresql: "postgresql",
  redis: "redis",
};

/**
 * Brand for a container image reference (`nginx:1.27`,
 * `ghcr.io/louislam/uptime-kuma@sha256:...`): drop the digest, registry,
 * and tag, then match the basename exactly.
 */
export function brandMarkKeyForImage(
  image: string | null | undefined
): BrandMarkKey | undefined {
  if (image == null) {
    return undefined;
  }
  const withoutDigest = image.trim().split("@", 1)[0] ?? "";
  const basename = withoutDigest.split("/").at(-1) ?? "";
  const withoutTag = basename.split(":", 1)[0] ?? "";
  return IMAGE_NAME_BRANDS[withoutTag.toLowerCase()];
}

export function brandMarkKeyForDatabaseEngine(
  engine: string | null | undefined
): BrandMarkKey | undefined {
  if (engine == null) {
    return undefined;
  }
  return DATABASE_ENGINE_BRANDS[engine.trim().toLowerCase()];
}
